# log_r_recruitment_process ----
## Setup ----
# The default model with distinct recruitment deviations in years 2 to 30.
data_4_model <- FIMSFrame(data_big)
log_devs_parameters <- setup_default_parameters(data_4_model)
is_log_devs <- log_devs_parameters[["label"]] %in% "log_devs"
deviations <- seq(-0.5, 0.5, length.out = sum(is_log_devs))
log_devs_parameters[["value"]][is_log_devs] <- deviations
recruitment_sd <- log_devs_parameters |>
  dplyr::filter(module_name == "Recruitment", label == "log_sd") |>
  dplyr::pull(value) |>
  exp()
log_devs_report <- log_devs_parameters |>
  initialize_fims(data = data_4_model) |>
  fit_fims(optimize = FALSE) |>
  get_report()

# The same model with log recruitment as the parameter. log R = log(R_hat) +
# deviation, where R_hat is the stock-recruit curve, gives the same
# recruitment, and the log_r process density, Normal(log(R_hat), sd), equals
# the deviation density, Normal(0, sd).
log_r <- log_devs_report[["log_expected_recruitment"]] + deviations
log_r_parameters <- log_devs_parameters |>
  dplyr::mutate(label = dplyr::if_else(label == "log_devs", "log_r", label))
log_r_parameters[["value"]][is_log_devs] <- log_r
log_r_report <- log_r_parameters |>
  initialize_fims(data = data_4_model) |>
  fit_fims(optimize = FALSE) |>
  get_report()

## IO correctness ----
test_that("`log_r_recruitment_process()` works with correct inputs", {
  #' @description Test that `log_r_recruitment_process(13, 12.5)` returns 12.5, the log recruitment itself, whatever the stock-recruit curve.
  expect_equal(
    object = FIMS:::log_r_recruitment_process(13, 12.5),
    expected = 12.5
  )
})

test_that("log_r and log_devs give the same model for the same recruitment", {
  # expected_recruitment has 31 values: the first year from the initial
  # numbers at age, years 2 to 30 from the process, and the year after.
  #' @description Test that recruitment in years 2 to 30 of a log_r model is exp(log_r).
  expect_equal(
    object = log(log_r_report[["expected_recruitment"]][[1]][2:30]),
    expected = log_r
  )
  #' @description Test that log_r = log(R_hat) + deviation gives the same recruitment in every year as log_devs = deviation.
  expect_equal(
    object = log_r_report[["expected_recruitment"]],
    expected = log_devs_report[["expected_recruitment"]]
  )
  #' @description Test that the recruitment process negative log-likelihood of the log_devs model is that of Normal(0, sd) deviations.
  expect_equal(
    object = log_devs_report[["nll_components"]][1],
    expected = -sum(stats::dnorm(deviations, 0, recruitment_sd, log = TRUE))
  )
  #' @description Test that the recruitment process negative log-likelihood of the log_r model equals that of the same deviations from log(R_hat).
  expect_equal(
    object = log_r_report[["nll_components"]][1],
    expected = -sum(stats::dnorm(deviations, 0, recruitment_sd, log = TRUE))
  )
  #' @description Test that log_r = log(R_hat) + deviation gives the same joint negative log-likelihood as log_devs = deviation.
  expect_equal(
    object = log_r_report[["jnll"]],
    expected = log_devs_report[["jnll"]]
  )
})

